// 02 - Validate Booking Data
const input = $json;

const fullName = (input['Full Name'] || input.fullName || '').toString().trim();
const email = (input['Email'] || input.email || '').toString().trim();
const phone = (input['Phone'] || input.phone || '').toString().trim();
const service = (input['Service'] || input.service || '').toString().trim();
const dateStr = (input['Preferred Date'] || input.preferredDate || '').toString().trim();
const timeStr = (input['Preferred Time'] || input.preferredTime || '').toString().trim();
const stylist = (input['Preferred Stylist'] || input.preferredStylist || 'Any Available').toString().trim();
const notes = (input['Notes'] || input.notes || '').toString().trim();
const rowNumber = input.row_number || input.__rowNumber || 2;

// Regex validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const phoneRegex = /^\+?[1-9]\d{6,14}$/;
const dateRegex = /^\d{4}-\d{2}-\d{2}$/;

const errors = [];
if (!fullName) errors.push('Missing Full Name');
if (!email || !emailRegex.test(email)) errors.push('Invalid or Missing Email');
if (!phone) errors.push('Missing Phone Number');
if (!service) errors.push('Missing Service');
if (!dateStr || !dateRegex.test(dateStr)) errors.push('Invalid or Missing Preferred Date (YYYY-MM-DD)');
if (!timeStr) errors.push('Missing Preferred Time');

const isValid = errors.length === 0;

return [{
  json: {
    isValid,
    errors,
    rowNumber,
    fullName,
    email,
    phone,
    service,
    stylist,
    preferredDate: dateStr,
    preferredTime: timeStr,
    notes,
    rawBooking: input
  }
}];

// 03 - Generate Unique Booking ID
const data = $json;
const timestamp = Date.now().toString().slice(-6);
const randomHex = Math.floor(Math.random() * 900 + 100).toString();
const bookingId = `SAL-${timestamp}${randomHex}`;

return [{
  json: {
    ...data,
    bookingId
  }
}];

// 04 - Evaluate Availability & Generate Alternatives if Conflict
const bookingData = $('03 - Generate Booking ID').item.json;
const existingEvents = $input.all();

const reqStart = new Date(`${bookingData.preferredDate}T${bookingData.preferredTime}:00`);
const reqEnd = new Date(reqStart.getTime() + 60 * 60 * 1000); // Assume 1 hour slot default for availability check

let hasConflict = false;
for (const evt of existingEvents) {
  if (!evt.json || !evt.json.start || !evt.json.end) continue;
  const evtStart = new Date(evt.json.start.dateTime || evt.json.start.date);
  const evtEnd = new Date(evt.json.end.dateTime || evt.json.end.date);

  if (reqStart < evtEnd && reqEnd > evtStart) {
    hasConflict = true;
    break;
  }
}

// Generate 3 alternative slots if unavailable
const alternatives = [];
if (hasConflict) {
  const alt1 = new Date(reqStart.getTime() + 2 * 60 * 60 * 1000);
  const alt2 = new Date(reqStart.getTime() + 24 * 60 * 60 * 1000);
  const alt3 = new Date(reqStart.getTime() + 48 * 60 * 60 * 1000);

  alternatives.push(alt1.toISOString().replace('T', ' ').slice(0, 16));
  alternatives.push(alt2.toISOString().replace('T', ' ').slice(0, 16));
  alternatives.push(alt3.toISOString().replace('T', ' ').slice(0, 16));
}

return [{
  json: {
    ...bookingData,
    isAvailable: !hasConflict,
    alternatives
  }
}];

