// Parse AI Response & Combine with Booking Data
const booking = $('04 - Evaluate Availability').item.json;
const aiRaw = $json.candidates[0].content.parts[0].text;

let aiParsed = {};
try {
  const cleanJson = aiRaw.replace(/```json|```/g, '').trim();
  aiParsed = JSON.parse(cleanJson);
} catch (e) {
  aiParsed = {
    durationMinutes: 60,
    prepTimeMinutes: 10,
    finishingTimeMinutes: 15,
    customerCategory: 'New Customer',
    suggestedUpsells: ['Deep Conditioning Treatment'],
    suggestedProducts: ['Nourishing Hair Serum'],
    futureAppointmentRec: 'Follow up in 6 weeks'
  };
}

const startDateTime = new Date(`${booking.preferredDate}T${booking.preferredTime}:00`);
const totalMinutes = (aiParsed.durationMinutes || 60) + (aiParsed.finishingTimeMinutes || 15);
const endDateTime = new Date(startDateTime.getTime() + totalMinutes * 60 * 1000);

const aiRecommendationSummary = `Category: ${aiParsed.customerCategory} | Duration: ${totalMinutes}m | Upsells: ${(aiParsed.suggestedUpsells||[]).join(', ')} | Products: ${(aiParsed.suggestedProducts||[]).join(', ')}`;

return [{
  json: {
    ...booking,
    ai: aiParsed,
    startISO: startDateTime.toISOString(),
    endISO: endDateTime.toISOString(),
    aiRecommendationSummary,
    customerType: aiParsed.customerCategory || 'New Customer'
  }
}];

